(function(root){
'use strict';
function csv(text){const rows=[];let row=[],v='',q=false;text=text.replace(/^\uFEFF/,'');for(let i=0;i<text.length;i++){const c=text[i];if(c==='"'){if(q&&text[i+1]==='"'){v+='"';i++;}else q=!q;}else if(!q&&(c===','||c==='\n'||c==='\r')){row.push(v);v='';if(c!==','){if(c==='\r'&&text[i+1]==='\n')i++;if(row.some(x=>x.trim()))rows.push(row);row=[];}}else v+=c;}if(q)throw Error('CSVの引用符が閉じていません。');row.push(v);if(row.some(x=>x.trim()))rows.push(row);if(rows.length<2)throw Error('見出しと価格データが必要です。');return rows;}
function parse(text,kind){const rows=csv(text),heads=rows.shift().map(x=>x.trim().toLowerCase());if(new Set(heads).size!==heads.length)throw Error('CSVの列名が重複しています。');const required=kind==='metals'?['date','silver','platinum']:['date','ny_dow_close','nikkei225_close'];for(const h of required)if(!heads.includes(h))throw Error('必要な列：'+required.join(', '));const result=[],seen=new Set();for(const [idx,row]of rows.entries()){if(row.length!==heads.length)throw Error((idx+2)+'行目：列数が見出しと一致しません。');const r={};for(const h of heads)r[h]=row[heads.indexOf(h)].trim();if(!/^\d{4}-\d{2}-\d{2}$/.test(r.date)||!Number.isFinite(Date.parse(r.date))||new Date(r.date).toISOString().slice(0,10)!==r.date)throw Error((idx+2)+'行目：日付はYYYY-MM-DDで指定してください。');if(r.date>new Date().toLocaleDateString('sv-SE',{timeZone:'Asia/Tokyo'}))throw Error('未来日付は取り込めません：'+r.date);if(seen.has(r.date))throw Error('日付が重複しています：'+r.date);seen.add(r.date);for(const h of required.filter(x=>x!=='date')){if(!r[h]||!Number.isFinite(+r[h])||+r[h]<=0)throw Error((idx+2)+'行目：'+h+'には正の価格が必要です。');r[h]=+r[h];}if(kind==='indices')for(const h of ['ny_dow_open','nikkei225_open']){if(h in r&&r[h]!==''){if(!Number.isFinite(+r[h])||+r[h]<=0)throw Error('始値には正の価格が必要です。');r[h]=+r[h];}else delete r[h];}result.push(r);}return result.sort((a,b)=>a.date.localeCompare(b.date));}
function derive(rows,kind){const data=rows.map((r,i)=>({...r,spread:kind==='metals'?3*r.silver-r.platinum:r.ny_dow_close-r.nikkei225_close}));for(let i=0;i<data.length;i++){const r=data[i];r.change=i?r.spread-data[i-1].spread:null;r.change10=i>=10?r.spread-data[i-10].spread:null;r.ma20=i>=19?data.slice(i-19,i+1).reduce((s,x)=>s+x.spread,0)/20:null;r.ma50=i>=49?data.slice(i-49,i+1).reduce((s,x)=>s+x.spread,0)/50:null;r.regime=r.ma50===null?'unknown':r.ma20<r.ma50?'contraction':r.ma20>r.ma50?'expansion':'flat';r.b=false;r.c2=false;r.v3=0;r.pullback=0;if(kind==='indices'){let j=i-1;while(j>=1&&data[j].change>0){r.pullback+=data[j].change;j--;}r.b=r.regime==='contraction'&&r.change<0&&r.pullback>=500;r.c2=r.b&&r.change10!==null&&r.change10<0;}else if(i>=6){const prior=data.slice(i-5,i).map(x=>x.change),sum=prior.reduce((s,x)=>s+x,0);if(prior.filter(x=>x<0).length>=3&&sum<=-300&&r.change>0&&r.spread<=2200)r.v3=1;else if(prior.filter(x=>x>0).length>=3&&sum>=300&&r.change<0&&r.spread>=2500)r.v3=-1;}}return data;}
function simulate(data,strategy){if(data.some(r=>!Number.isFinite(r.ny_dow_open)||!Number.isFinite(r.nikkei225_open)))return {available:false};let position=null,pendingEntry=null,pendingExit=null;const trades=[];for(let i=0;i<data.length;i++){const r=data[i];if(position&&pendingExit){trades.push({...position,exit:r.date,exitSpread:r.ny_dow_open-r.nikkei225_open,reason:pendingExit});position=null;pendingExit=null;}if(pendingEntry){position={date:r.date,entry:r.ny_dow_open-r.nikkei225_open,index:i};pendingEntry=null;}if(position){const pnl=position.entry-r.spread,held=i-position.index+1;position.pnl=pnl;position.held=held;pendingExit=pnl<=-2000?'損切り':pnl>=1000?'利確':held>=30?'保有期限':null;}if(r.date>='2026-10-03'&&r[strategy]&&!position)pendingEntry={date:r.date};}return {available:true,position,pendingEntry,pendingExit,trades};}
root.SpreadEngine={parse,derive,simulate};if(typeof module!=='undefined')module.exports=root.SpreadEngine;
})(typeof window!=='undefined'?window:globalThis);
